package fr.cercle.aplomb; import java.util.*; public final class Mechanics {public static float brake(float v,float dt,float f){return Math.max(0,v-f*dt);}public static boolean stable(ArrayList<float[]> b){for(int i=0;i<b.size()-1;i++){float mass=0,sum=0;for(int j=i+1;j<b.size();j++){mass+=b.get(j)[2];sum+=b.get(j)[0]*b.get(j)[2];}float[] s=b.get(i);if(sum/mass<s[0]-s[2]/2||sum/mass>s[0]+s[2]/2)return false;}return true;}}